INSERT INTO public.packages (name,slug,category,description,duration_minutes,total_questions,is_free,is_published)
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang teknisi lapangan PLN bekerja di ketinggian untuk memperbaiki jaringan listrik. Meskipun sudah terbiasa, ia selalu menggunakan alat pelindung diri dengan lengkap karena menyadari risiko bahaya yang ada. Proses mental yang membuatnya menyadari dan menafsirkan bahaya di sekitarnya disebut...','[{"key": "A", "text": "Motivasi"}, {"key": "B", "text": "Emosi"}, {"key": "C", "text": "Persepsi"}, {"key": "D", "text": "Kepribadian"}]'::jsonb,'A','Persepsi adalah proses aktif dimana otak menyeleksi, mengorganisir, dan menginterpretasikan informasi yang diterima melalui panca indera untuk memahaminya. Dalam kasus ini, teknisi tidak hanya melihat ketinggian (sensasi), tetapi juga menafsirkannya sebagai sesuatu yang berisiko (persepsi), yang kemudian memengaruhi perilakunya untuk memakai APD.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang karyawan administrasi di kantor PLN Unit Induk Distribusi (UID) selalu menyelesaikan pekerjaannya tepat waktu karena ia menyukai tantangan dan merasa puas ketika berhasil menata data dengan rapi. Dorongan yang berasal dari dalam diri karyawan tersebut dikenal sebagai...','[{"key": "A", "text": "Motivasi ekstrinsik"}, {"key": "B", "text": "Motivasi intrinsik"}, {"key": "C", "text": "Motivasi afiliasi"}, {"key": "D", "text": "Motivasi kekuasaan"}]'::jsonb,'A','Motivasi intrinsik datang dari dalam individu, didorong oleh kepuasan pribadi, minat, atau tantangan dari pekerjaan itu sendiri. Hal ini berbeda dengan motivasi ekstrinsik yang didorong oleh faktor luar seperti gaji, bonus, atau pujian dari atasan.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ketika menghadapi keluhan pelanggan mengenai pemadaman listrik yang lama, seorang staf layanan pelanggan PLN tetap tenang, mendengarkan dengan empati, dan memberikan penjelasan yang solutif. Kemampuan untuk mengelola emosi diri sendiri dan orang lain ini disebut...','[{"key": "A", "text": "Kecerdasan intelektual (IQ)"}, {"key": "B", "text": "Kecerdasan emosional (EQ)"}, {"key": "C", "text": "Kecerdasan spiritual (SQ)"}, {"key": "D", "text": "Kemampuan kognitif"}]'::jsonb,'A','EQ adalah kemampuan untuk mengenali, memahami, dan mengatur emosi sendiri (tetap tenang saat ditekan) serta mengenali dan memengaruhi emosi orang lain (empati kepada pelanggan). Kemampuan ini krusial dalam peran yang berhadapan langsung dengan pelanggan.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam model kepribadian "The Big Five", sifat yang paling menggambarkan individu yang terorganisir, bertanggung jawab, dan dapat diandalkan, yang sangat penting untuk peran sebagai auditor internal di PLN, adalah...','[{"key": "A", "text": "Extraversion (Ekstraversi)"}, {"key": "B", "text": "Agreeableness (Mudah Akur)"}, {"key": "C", "text": "Conscientiousness (Sifat Berhati-hati)"}, {"key": "D", "text": "Neuroticism (Neurotisisme)"}]'::jsonb,'A','Conscientiousness adalah dimensi kepribadian yang paling kuat dalam memprediksi kinerja di berbagai pekerjaan, terutama yang menuntut keteraturan, keandalan, dan tanggung jawab seperti auditor. Sifat lain seperti Extraversion (mudah bergaul) atau Agreeableness (kooperatif) mungkin berguna, tetapi tidak sepenting sifat ini untuk peran tersebut.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer di PLN cenderung memberikan penilaian kinerja yang lebih tinggi kepada anggota tim yang merupakan almamater universitas yang sama dengannya. Bias dalam persepsi ini dikenal sebagai...','[{"key": "A", "text": "Efek Halo"}, {"key": "B", "text": "Stereotip"}, {"key": "C", "text": "Similar-to-me effect"}, {"key": "D", "text": "Proyeksi"}]'::jsonb,'A','Ini adalah bias persepsi spesifik di mana kita cenderung menilai lebih positif orang yang kita anggap mirip dengan kita (misalnya, dari almamater, suku, atau hobi yang sama). Ini berbeda dari Efek Halo, di mana satu karakteristik positif (misalnya, penampilan menarik) memengaruhi penilaian secara keseluruhan.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Di tengah krisis pemadaman listrik skala besar akibat bencana alam, seorang manajer unit harus mengambil keputusan cepat. Kemampuannya untuk tetap berpikir jernih dan tidak panik sangat dipengaruhi oleh...','[{"key": "A", "text": "Regulasi emosi"}, {"key": "B", "text": "Motivasi berprestasi"}, {"key": "C", "text": "Persepsi sensorik"}, {"key": "D", "text": "Tipe kepribadian introvert"}]'::jsonb,'A','Regulasi emosi adalah komponen inti dari kecerdasan emosional. Ini adalah kemampuan untuk mengendalikan atau mengarahkan ulang impuls dan suasana hati yang disruptif, memungkinkan seseorang untuk berpikir jernih di bawah tekanan dan tidak membuat keputusan impulsif.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses adaptasi seorang pegawai baru terhadap nilai-nilai, norma, dan cara kerja yang berlaku di lingkungan PLN disebut...','[{"key": "A", "text": "Sosialisasi organisasi"}, {"key": "B", "text": "Orientasi kerja"}, {"key": "C", "text": "Pelatihan teknis"}, {"key": "D", "text": "Penilaian kepribadian"}]'::jsonb,'A','Sosialisasi adalah proses adaptasi budaya yang mendalam dan berkelanjutan. Ini lebih luas dari ''orientasi kerja'' yang biasanya merupakan acara pengenalan formal di awal, dan berbeda dari ''pelatihan teknis'' yang berfokus pada keterampilan spesifik pekerjaan.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut Teori Hierarki Kebutuhan Maslow, penyediaan helm, sepatu keselamatan, dan sarung tangan bagi teknisi lapangan PLN bertujuan untuk memenuhi kebutuhan pada tingkat...','[{"key": "A", "text": "Fisiologis"}, {"key": "B", "text": "Rasa Aman"}, {"key": "C", "text": "Sosial"}, {"key": "D", "text": "Aktualisasi Diri"}]'::jsonb,'A','Dalam hierarki Maslow, setelah kebutuhan dasar fisiologis (udara, makanan, air) terpenuhi, individu termotivasi oleh kebutuhan akan keamanan dan keselamatan (safety needs), baik fisik maupun finansial. APD secara langsung bertujuan untuk melindungi keselamatan fisik pekerja.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manajemen PLN memutuskan untuk memperbaiki kualitas pencahayaan dan suhu ruangan di kantor agar lebih nyaman. Menurut Teori Dua Faktor Herzberg, perbaikan ini termasuk dalam...','[{"key": "A", "text": "Motivator Factors (Faktor Pendorong)"}, {"key": "B", "text": "Hygiene Factors (Faktor Kebersihan)"}, {"key": "C", "text": "Satisfaction Factors (Faktor Kepuasan)"}, {"key": "D", "text": "Achievement Factors (Faktor Prestasi)"}]'::jsonb,'A','Teori Herzberg membedakan antara faktor yang menyebabkan ketidakpuasan (Hygiene Factors) dan yang menyebabkan kepuasan (Motivators). Kondisi kerja yang baik (pencahayaan, suhu) tidak akan membuat karyawan termotivasi luar biasa, tetapi jika buruk, akan menyebabkan keluhan dan ketidakpuasan.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Stres kerja yang berkepanjangan pada operator control room pembangkit listrik dapat menyebabkan penurunan konsentrasi dan kelelahan, yang pada akhirnya berdampak negatif pada...','[{"key": "A", "text": "Kepuasan pelanggan"}, {"key": "B", "text": "Kinerja dan keselamatan kerja"}, {"key": "C", "text": "Struktur organisasi"}, {"key": "D", "text": "Program pelatihan"}]'::jsonb,'A','Stres kronis menguras sumber daya kognitif, menyebabkan penurunan kewaspadaan, konsentrasi, dan waktu reaksi. Di lingkungan berisiko tinggi seperti control room pembangkit listrik, penurunan fungsi kognitif ini secara langsung meningkatkan kemungkinan kesalahan operasional yang fatal.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu ciri utama dari sebuah tim kerja (teamwork) yang efektif di unit pemeliharaan gardu induk PLN adalah...','[{"key": "A", "text": "Setiap anggota bekerja sendiri-sendiri untuk mencapai target individu."}, {"key": "B", "text": "Adanya tujuan bersama dan saling ketergantungan antar anggota."}, {"key": "C", "text": "Persaingan yang tinggi antar anggota tim untuk menjadi yang terbaik."}, {"key": "D", "text": "Pemimpin mengambil semua keputusan tanpa masukan dari anggota."}]'::jsonb,'A','Inilah yang membedakan sebuah tim dari sekadar sekelompok orang yang bekerja di tempat yang sama. Anggota tim yang efektif memahami bahwa mereka tidak bisa berhasil secara individu tanpa kontribusi dan kerja sama dari anggota lain untuk mencapai satu tujuan yang sama.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer unit layanan PLN yang sering turun ke lapangan, memberikan visi yang menginspirasi, dan mendorong timnya untuk berinovasi dalam pelayanan menunjukkan gaya kepemimpinan...','[{"key": "A", "text": "Otoriter"}, {"key": "B", "text": "Transaksional"}, {"key": "C", "text": "Laissez-faire"}, {"key": "D", "text": "Transformasional"}]'::jsonb,'A','Gaya kepemimpinan ini melampaui sekadar pertukaran imbalan (transaksional). Pemimpin transformasional menginspirasi tim dengan visi, menantang mereka untuk berpikir kreatif (inovasi), dan bertindak sebagai panutan, sehingga memotivasi tim untuk berkinerja melebihi ekspektasi.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tingkat komitmen, semangat, dan keterikatan emosional seorang karyawan terhadap pekerjaannya dan tujuan organisasi PLN disebut...','[{"key": "A", "text": "Kepuasan kerja"}, {"key": "B", "text": "Keterlibatan karyawan (employee engagement)"}, {"key": "C", "text": "Motivasi kerja"}, {"key": "D", "text": "Loyalitas karyawan"}]'::jsonb,'A','Engagement adalah tingkat keterlibatan dan antusiasme karyawan yang mendalam terhadap pekerjaan dan perusahaan. Ini lebih dari sekadar kepuasan (merasa cukup senang) atau loyalitas (tidak ingin pindah), karena mencakup kemauan untuk memberikan upaya ekstra.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penyebab utama stres bagi staf di PLN Contact Center 123 sering kali adalah...','[{"key": "A", "text": "Beban kerja yang monoton"}, {"key": "B", "text": "Tuntutan emosional saat berinteraksi dengan pelanggan yang marah"}, {"key": "C", "text": "Kurangnya fasilitas kerja"}, {"key": "D", "text": "Gaji yang tidak sesuai"}]'::jsonb,'A','Stresor ini dikenal sebagai emotional labor, yaitu upaya untuk menampilkan emosi yang sesuai dengan tuntutan pekerjaan (misalnya, tetap ramah saat dimarahi). Mengelola kesenjangan antara emosi yang dirasakan dan yang ditampilkan ini bisa sangat melelahkan secara mental.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kepuasan kerja seorang karyawan di PLN dapat dipengaruhi secara positif oleh...','[{"key": "A", "text": "Tingkat konflik yang tinggi dengan rekan kerja."}, {"key": "B", "text": "Ketidakjelasan peran dan tanggung jawab."}, {"key": "C", "text": "Kesempatan untuk pengembangan karir dan promosi."}, {"key": "D", "text": "Pengawasan yang terlalu ketat dari atasan."}]'::jsonb,'A','Menurut banyak teori motivasi, kesempatan untuk tumbuh, belajar, dan maju adalah salah satu pendorong kepuasan kerja yang paling kuat. Ini memenuhi kebutuhan tingkat tinggi seperti penghargaan (esteem) dan aktualisasi diri.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam survei kepuasan karyawan di PLN, responden diminta untuk memberikan tanggapan pada skala dari 1 (Sangat Tidak Setuju) hingga 5 (Sangat Setuju). Skala pengukuran ini adalah contoh dari...','[{"key": "A", "text": "Skala Guttman"}, {"key": "B", "text": "Skala Thurstone"}, {"key": "C", "text": "Skala Likert"}, {"key": "D", "text": "Skala Diferensial Semantik"}]'::jsonb,'A','Skala Likert adalah format respons yang paling umum digunakan dalam survei untuk mengukur sikap. Responden diminta untuk menilai tingkat persetujuan mereka terhadap serangkaian pernyataan, biasanya dalam skala 5 atau 7 poin.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah tes kemampuan teknis untuk calon operator pembangkit di PLN dikatakan memiliki reliabilitas tinggi jika...','[{"key": "A", "text": "Tes tersebut benar-benar mengukur kemampuan teknis yang dibutuhkan."}, {"key": "B", "text": "Hasil tes seorang kandidat konsisten atau stabil ketika diukur berulang kali."}, {"key": "C", "text": "Tes tersebut disukai oleh para peserta tes."}, {"key": "D", "text": "Soal-soal dalam tes tersebut dianggap mudah."}]'::jsonb,'A','Reliabilitas adalah tentang konsistensi. Bayangkan sebuah timbangan yang menunjukkan berat yang berbeda setiap kali Anda menaikinya; timbangan itu tidak reliabel. Demikian pula, tes yang reliabel akan memberikan hasil yang konsisten jika tidak ada perubahan nyata pada kemampuan yang diukur. Jawaban (a) lebih mengacu pada validitas.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tim rekrutmen PLN menemukan bahwa kandidat yang mendapat skor tinggi pada tes simulasi kerja cenderung menunjukkan kinerja yang sangat baik setelah diterima bekerja. Hal ini menunjukkan bahwa tes simulasi tersebut memiliki...','[{"key": "A", "text": "Validitas isi (content validity)"}, {"key": "B", "text": "Validitas prediktif (predictive validity)"}, {"key": "C", "text": "Reliabilitas tes-ulang (test-retest reliability)"}, {"key": "D", "text": "Konsistensi internal"}]'::jsonb,'A','Validitas adalah tentang apakah tes mengukur apa yang seharusnya diukur. Validitas prediktif secara spesifik menunjukkan seberapa baik sebuah tes dapat memprediksi hasil di masa depan (dalam hal ini, kinerja kerja). Skor tes yang tinggi berkorelasi dengan kinerja yang tinggi, membuktikan nilai prediktif tes tersebut.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang calon pegawai PLN mendapatkan skor sangat tinggi pada aspek conscientiousness. Tim asesor SDM dapat menginterpretasikan hasil ini sebagai indikasi bahwa kandidat tersebut kemungkinan besar adalah seorang yang...','[{"key": "A", "text": "Sangat kreatif dan suka bergaul."}, {"key": "B", "text": "Cenderung mudah cemas dan gugup."}, {"key": "C", "text": "Terorganisir, teliti, dan bertanggung jawab."}, {"key": "D", "text": "Sangat dominan dan suka memimpin."}]'::jsonb,'A','Ini adalah ciri-ciri inti dari individu dengan skor conscientiousness yang tinggi. Opsi lain menggambarkan dimensi kepribadian yang berbeda: (a) terkait dengan Extraversion dan Openness, (b) terkait dengan Neuroticism yang tinggi, dan (d) terkait dengan Extraversion yang tinggi.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama penggunaan alat tes psikometri yang terstandarisasi dalam proses rekrutmen massal di PLN adalah untuk...','[{"key": "A", "text": "Mengurangi biaya rekrutmen."}, {"key": "B", "text": "Mempercepat proses seleksi tanpa memperhatikan kualitas."}, {"key": "C", "text": "Memastikan penilaian yang objektif dan adil bagi semua kandidat."}, {"key": "D", "text": "Menemukan kandidat yang paling ekstrovert."}]'::jsonb,'A','Standardisasi dalam tes psikometri berarti semua kandidat menerima instruksi, batasan waktu, dan soal yang sama, serta dinilai dengan cara yang sama. Ini meminimalkan bias subjektif dari penilai dan menciptakan proses seleksi yang lebih adil dan dapat dipertahankan.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang teknisi lapangan PLN bekerja di ketinggian untuk memperbaiki jaringan listrik. Meskipun sudah terbiasa, ia selalu menggunakan alat pelindung diri dengan lengkap karena menyadari risiko bahaya yang ada. Proses mental yang membuatnya menyadari dan menafsirkan bahaya di sekitarnya disebut...','[{"key": "A", "text": "Motivasi"}, {"key": "B", "text": "Emosi"}, {"key": "C", "text": "Persepsi"}, {"key": "D", "text": "Kepribadian"}]'::jsonb,'A','Persepsi adalah proses aktif dimana otak menyeleksi, mengorganisir, dan menginterpretasikan informasi yang diterima melalui panca indera untuk memahaminya. Dalam kasus ini, teknisi tidak hanya melihat ketinggian (sensasi), tetapi juga menafsirkannya sebagai sesuatu yang berisiko (persepsi), yang kemudian memengaruhi perilakunya untuk memakai APD.','AKDING',1);
