  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Di tengah krisis pemadaman listrik skala besar akibat bencana alam, seorang manajer unit harus mengambil keputusan cepat. Kemampuannya untuk tetap berpikir jernih dan tidak panik sangat dipengaruhi oleh...','[{"key": "A", "text": "Regulasi emosi"}, {"key": "B", "text": "Motivasi berprestasi"}, {"key": "C", "text": "Persepsi sensorik"}, {"key": "D", "text": "Tipe kepribadian introvert"}]'::jsonb,'A','Regulasi emosi adalah komponen inti dari kecerdasan emosional. Ini adalah kemampuan untuk mengendalikan atau mengarahkan ulang impuls dan suasana hati yang disruptif, memungkinkan seseorang untuk berpikir jernih di bawah tekanan dan tidak membuat keputusan impulsif.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses adaptasi seorang pegawai baru terhadap nilai-nilai, norma, dan cara kerja yang berlaku di lingkungan PLN disebut...','[{"key": "A", "text": "Sosialisasi organisasi"}, {"key": "B", "text": "Orientasi kerja"}, {"key": "C", "text": "Pelatihan teknis"}, {"key": "D", "text": "Penilaian kepribadian"}]'::jsonb,'A','Sosialisasi adalah proses adaptasi budaya yang mendalam dan berkelanjutan. Ini lebih luas dari ''orientasi kerja'' yang biasanya merupakan acara pengenalan formal di awal, dan berbeda dari ''pelatihan teknis'' yang berfokus pada keterampilan spesifik pekerjaan.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut Teori Hierarki Kebutuhan Maslow, penyediaan helm, sepatu keselamatan, dan sarung tangan bagi teknisi lapangan PLN bertujuan untuk memenuhi kebutuhan pada tingkat...','[{"key": "A", "text": "Fisiologis"}, {"key": "B", "text": "Rasa Aman"}, {"key": "C", "text": "Sosial"}, {"key": "D", "text": "Aktualisasi Diri"}]'::jsonb,'A','Dalam hierarki Maslow, setelah kebutuhan dasar fisiologis (udara, makanan, air) terpenuhi, individu termotivasi oleh kebutuhan akan keamanan dan keselamatan (safety needs), baik fisik maupun finansial. APD secara langsung bertujuan untuk melindungi keselamatan fisik pekerja.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manajemen PLN memutuskan untuk memperbaiki kualitas pencahayaan dan suhu ruangan di kantor agar lebih nyaman. Menurut Teori Dua Faktor Herzberg, perbaikan ini termasuk dalam...','[{"key": "A", "text": "Motivator Factors (Faktor Pendorong)"}, {"key": "B", "text": "Hygiene Factors (Faktor Kebersihan)"}, {"key": "C", "text": "Satisfaction Factors (Faktor Kepuasan)"}, {"key": "D", "text": "Achievement Factors (Faktor Prestasi)"}]'::jsonb,'A','Teori Herzberg membedakan antara faktor yang menyebabkan ketidakpuasan (Hygiene Factors) dan yang menyebabkan kepuasan (Motivators). Kondisi kerja yang baik (pencahayaan, suhu) tidak akan membuat karyawan termotivasi luar biasa, tetapi jika buruk, akan menyebabkan keluhan dan ketidakpuasan.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Stres kerja yang berkepanjangan pada operator control room pembangkit listrik dapat menyebabkan penurunan konsentrasi dan kelelahan, yang pada akhirnya berdampak negatif pada...','[{"key": "A", "text": "Kepuasan pelanggan"}, {"key": "B", "text": "Kinerja dan keselamatan kerja"}, {"key": "C", "text": "Struktur organisasi"}, {"key": "D", "text": "Program pelatihan"}]'::jsonb,'A','Stres kronis menguras sumber daya kognitif, menyebabkan penurunan kewaspadaan, konsentrasi, dan waktu reaksi. Di lingkungan berisiko tinggi seperti control room pembangkit listrik, penurunan fungsi kognitif ini secara langsung meningkatkan kemungkinan kesalahan operasional yang fatal.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu ciri utama dari sebuah tim kerja (teamwork) yang efektif di unit pemeliharaan gardu induk PLN adalah...','[{"key": "A", "text": "Setiap anggota bekerja sendiri-sendiri untuk mencapai target individu."}, {"key": "B", "text": "Adanya tujuan bersama dan saling ketergantungan antar anggota."}, {"key": "C", "text": "Persaingan yang tinggi antar anggota tim untuk menjadi yang terbaik."}, {"key": "D", "text": "Pemimpin mengambil semua keputusan tanpa masukan dari anggota."}]'::jsonb,'A','Inilah yang membedakan sebuah tim dari sekadar sekelompok orang yang bekerja di tempat yang sama. Anggota tim yang efektif memahami bahwa mereka tidak bisa berhasil secara individu tanpa kontribusi dan kerja sama dari anggota lain untuk mencapai satu tujuan yang sama.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer unit layanan PLN yang sering turun ke lapangan, memberikan visi yang menginspirasi, dan mendorong timnya untuk berinovasi dalam pelayanan menunjukkan gaya kepemimpinan...','[{"key": "A", "text": "Otoriter"}, {"key": "B", "text": "Transaksional"}, {"key": "C", "text": "Laissez-faire"}, {"key": "D", "text": "Transformasional"}]'::jsonb,'A','Gaya kepemimpinan ini melampaui sekadar pertukaran imbalan (transaksional). Pemimpin transformasional menginspirasi tim dengan visi, menantang mereka untuk berpikir kreatif (inovasi), dan bertindak sebagai panutan, sehingga memotivasi tim untuk berkinerja melebihi ekspektasi.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tingkat komitmen, semangat, dan keterikatan emosional seorang karyawan terhadap pekerjaannya dan tujuan organisasi PLN disebut...','[{"key": "A", "text": "Kepuasan kerja"}, {"key": "B", "text": "Keterlibatan karyawan (employee engagement)"}, {"key": "C", "text": "Motivasi kerja"}, {"key": "D", "text": "Loyalitas karyawan"}]'::jsonb,'A','Engagement adalah tingkat keterlibatan dan antusiasme karyawan yang mendalam terhadap pekerjaan dan perusahaan. Ini lebih dari sekadar kepuasan (merasa cukup senang) atau loyalitas (tidak ingin pindah), karena mencakup kemauan untuk memberikan upaya ekstra.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penyebab utama stres bagi staf di PLN Contact Center 123 sering kali adalah...','[{"key": "A", "text": "Beban kerja yang monoton"}, {"key": "B", "text": "Tuntutan emosional saat berinteraksi dengan pelanggan yang marah"}, {"key": "C", "text": "Kurangnya fasilitas kerja"}, {"key": "D", "text": "Gaji yang tidak sesuai"}]'::jsonb,'A','Stresor ini dikenal sebagai emotional labor, yaitu upaya untuk menampilkan emosi yang sesuai dengan tuntutan pekerjaan (misalnya, tetap ramah saat dimarahi). Mengelola kesenjangan antara emosi yang dirasakan dan yang ditampilkan ini bisa sangat melelahkan secara mental.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kepuasan kerja seorang karyawan di PLN dapat dipengaruhi secara positif oleh...','[{"key": "A", "text": "Tingkat konflik yang tinggi dengan rekan kerja."}, {"key": "B", "text": "Ketidakjelasan peran dan tanggung jawab."}, {"key": "C", "text": "Kesempatan untuk pengembangan karir dan promosi."}, {"key": "D", "text": "Pengawasan yang terlalu ketat dari atasan."}]'::jsonb,'A','Menurut banyak teori motivasi, kesempatan untuk tumbuh, belajar, dan maju adalah salah satu pendorong kepuasan kerja yang paling kuat. Ini memenuhi kebutuhan tingkat tinggi seperti penghargaan (esteem) dan aktualisasi diri.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam survei kepuasan karyawan di PLN, responden diminta untuk memberikan tanggapan pada skala dari 1 (Sangat Tidak Setuju) hingga 5 (Sangat Setuju). Skala pengukuran ini adalah contoh dari...','[{"key": "A", "text": "Skala Guttman"}, {"key": "B", "text": "Skala Thurstone"}, {"key": "C", "text": "Skala Likert"}, {"key": "D", "text": "Skala Diferensial Semantik"}]'::jsonb,'A','Skala Likert adalah format respons yang paling umum digunakan dalam survei untuk mengukur sikap. Responden diminta untuk menilai tingkat persetujuan mereka terhadap serangkaian pernyataan, biasanya dalam skala 5 atau 7 poin.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah tes kemampuan teknis untuk calon operator pembangkit di PLN dikatakan memiliki reliabilitas tinggi jika...','[{"key": "A", "text": "Tes tersebut benar-benar mengukur kemampuan teknis yang dibutuhkan."}, {"key": "B", "text": "Hasil tes seorang kandidat konsisten atau stabil ketika diukur berulang kali."}, {"key": "C", "text": "Tes tersebut disukai oleh para peserta tes."}, {"key": "D", "text": "Soal-soal dalam tes tersebut dianggap mudah."}]'::jsonb,'A','Reliabilitas adalah tentang konsistensi. Bayangkan sebuah timbangan yang menunjukkan berat yang berbeda setiap kali Anda menaikinya; timbangan itu tidak reliabel. Demikian pula, tes yang reliabel akan memberikan hasil yang konsisten jika tidak ada perubahan nyata pada kemampuan yang diukur. Jawaban (a) lebih mengacu pada validitas.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tim rekrutmen PLN menemukan bahwa kandidat yang mendapat skor tinggi pada tes simulasi kerja cenderung menunjukkan kinerja yang sangat baik setelah diterima bekerja. Hal ini menunjukkan bahwa tes simulasi tersebut memiliki...','[{"key": "A", "text": "Validitas isi (content validity)"}, {"key": "B", "text": "Validitas prediktif (predictive validity)"}, {"key": "C", "text": "Reliabilitas tes-ulang (test-retest reliability)"}, {"key": "D", "text": "Konsistensi internal"}]'::jsonb,'A','Validitas adalah tentang apakah tes mengukur apa yang seharusnya diukur. Validitas prediktif secara spesifik menunjukkan seberapa baik sebuah tes dapat memprediksi hasil di masa depan (dalam hal ini, kinerja kerja). Skor tes yang tinggi berkorelasi dengan kinerja yang tinggi, membuktikan nilai prediktif tes tersebut.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang calon pegawai PLN mendapatkan skor sangat tinggi pada aspek conscientiousness. Tim asesor SDM dapat menginterpretasikan hasil ini sebagai indikasi bahwa kandidat tersebut kemungkinan besar adalah seorang yang...','[{"key": "A", "text": "Sangat kreatif dan suka bergaul."}, {"key": "B", "text": "Cenderung mudah cemas dan gugup."}, {"key": "C", "text": "Terorganisir, teliti, dan bertanggung jawab."}, {"key": "D", "text": "Sangat dominan dan suka memimpin."}]'::jsonb,'A','Ini adalah ciri-ciri inti dari individu dengan skor conscientiousness yang tinggi. Opsi lain menggambarkan dimensi kepribadian yang berbeda: (a) terkait dengan Extraversion dan Openness, (b) terkait dengan Neuroticism yang tinggi, dan (d) terkait dengan Extraversion yang tinggi.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama penggunaan alat tes psikometri yang terstandarisasi dalam proses rekrutmen massal di PLN adalah untuk...','[{"key": "A", "text": "Mengurangi biaya rekrutmen."}, {"key": "B", "text": "Mempercepat proses seleksi tanpa memperhatikan kualitas."}, {"key": "C", "text": "Memastikan penilaian yang objektif dan adil bagi semua kandidat."}, {"key": "D", "text": "Menemukan kandidat yang paling ekstrovert."}]'::jsonb,'A','Standardisasi dalam tes psikometri berarti semua kandidat menerima instruksi, batasan waktu, dan soal yang sama, serta dinilai dengan cara yang sama. Ini meminimalkan bias subjektif dari penilai dan menciptakan proses seleksi yang lebih adil dan dapat dipertahankan.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Interpretasi hasil tes psikologi yang dilakukan oleh pihak yang tidak memiliki kualifikasi dapat menyebabkan...','[{"key": "A", "text": "Peningkatan objektivitas seleksi."}, {"key": "B", "text": "Kesalahan dalam pengambilan keputusan terkait kandidat."}, {"key": "C", "text": "Penghematan anggaran perusahaan."}, {"key": "D", "text": "Peningkatan motivasi peserta tes."}]'::jsonb,'A','Hasil tes psikologi bukanlah data yang sederhana; interpretasinya memerlukan pemahaman tentang teori psikologi, statistik, dan konteks pekerjaan. Interpretasi yang salah oleh orang yang tidak terlatih dapat menyebabkan perusahaan salah menilai potensi kandidat.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Langkah paling awal dan fundamental yang harus dilakukan oleh departemen SDM PLN sebelum mempublikasikan lowongan untuk posisi "Analis Sistem Kelistrikan" adalah...','[{"key": "A", "text": "Menentukan besaran gaji."}, {"key": "B", "text": "Melakukan analisis jabatan (job analysis)."}, {"key": "C", "text": "Merancang program training."}, {"key": "D", "text": "Menyiapkan tes wawancara."}]'::jsonb,'A','Analisis jabatan adalah batu fondasi dari semua praktik SDM. Proses ini mengidentifikasi tugas, tanggung jawab, dan kualifikasi (pengetahuan, keterampilan, kemampuan) yang dibutuhkan. Tanpa informasi ini, perusahaan tidak tahu kriteria apa yang harus dicari pada kandidat.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'"Coba ceritakan pengalaman Anda ketika harus mengatasi masalah teknis yang tak terduga di lapangan." Pertanyaan ini merupakan contoh dari teknik wawancara...','[{"key": "A", "text": "Wawancara terstruktur"}, {"key": "B", "text": "Wawancara stres"}, {"key": "C", "text": "Behavioral Event Interview (BEI)"}, {"key": "D", "text": "Wawancara tidak terstruktur"}]'::jsonb,'A','Pertanyaan ini secara eksplisit meminta contoh perilaku di masa lalu ("ceritakan pengalaman Anda"). Prinsip di balik BEI adalah bahwa perilaku masa lalu adalah prediktor terbaik dari perilaku di masa depan. Jawaban kandidat biasanya dievaluasi menggunakan metode STAR (Situation, Task, Action, Result).','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip objektivitas dalam proses seleksi PLN berarti bahwa...','[{"key": "A", "text": "Keputusan penerimaan didasarkan pada kualifikasi dan kompetensi, bukan pada hubungan personal atau bias."}, {"key": "B", "text": "Semua kandidat harus berasal dari universitas terkemuka."}, {"key": "C", "text": "Proses wawancara dilakukan oleh satu orang saja untuk konsistensi."}, {"key": "D", "text": "Hanya kandidat dengan pengalaman kerja yang diterima."}]'::jsonb,'A','Objektivitas dalam seleksi berarti menggunakan kriteria yang relevan dengan pekerjaan dan menerapkannya secara konsisten pada semua kandidat, untuk memastikan keputusan dibuat berdasarkan kemampuan, bukan faktor-faktor yang tidak relevan.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pelatihan yang diberikan kepada teknisi baru PLN dengan cara langsung bekerja di gardu induk di bawah bimbingan seorang senior disebut...','[{"key": "A", "text": "Off-the-job training"}, {"key": "B", "text": "Simulasi"}, {"key": "C", "text": "Studi kasus"}, {"key": "D", "text": "On-the-job training"}]'::jsonb,'A','Metode ini melibatkan pembelajaran dengan melakukan pekerjaan secara langsung di lingkungan kerja yang sesungguhnya. Ini sangat efektif untuk pekerjaan teknis karena memberikan pengalaman praktis. Ini berbeda dengan off-the-job training yang dilakukan di luar lokasi kerja (misalnya, di kelas atau seminar).','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari program management trainee (MT) di PLN adalah...','[{"key": "A", "text": "Mengisi kekosongan jabatan level staf dengan cepat."}, {"key": "B", "text": "Mempersiapkan kader-kader pemimpin masa depan perusahaan."}, {"key": "C", "text": "Memberikan pengalaman kerja sementara bagi lulusan baru."}, {"key": "D", "text": "Mengurangi tingkat pengangguran sarjana."}]'::jsonb,'A','Program MT adalah investasi strategis jangka panjang. Tujuannya adalah untuk merekrut talenta berpotensi tinggi dan mengakselerasi pengembangan mereka melalui pelatihan intensif dan rotasi di berbagai departemen, sehingga mereka siap untuk mengisi posisi manajerial di masa depan.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu kelemahan jika proses seleksi hanya mengandalkan wawancara tanpa didukung alat tes lain adalah...','[{"key": "A", "text": "Membutuhkan biaya yang sangat besar."}, {"key": "B", "text": "Terlalu memakan waktu yang lama."}, {"key": "C", "text": "Rentan terhadap subjektivitas dan bias dari pewawancara."}, {"key": "D", "text": "Sulit untuk mengukur kemampuan teknis."}]'::jsonb,'A','Pewawancara adalah manusia yang rentan terhadap berbagai bias (misalnya, bias kesan pertama, efek halo, bias kesamaan). Tanpa didukung oleh alat ukur yang lebih objektif seperti tes kemampuan atau tes psikometri, keputusan seleksi bisa menjadi sangat tidak andal.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Program pelatihan yang paling efektif untuk meningkatkan keterampilan komunikasi tim pelayanan teknik PLN dalam menghadapi pelanggan adalah...','[{"key": "A", "text": "Pelatihan teknis tentang jaringan listrik."}, {"key": "B", "text": "Seminar tentang K3 (Keselamatan dan Kesehatan Kerja)."}, {"key": "C", "text": "Role-playing atau bermain peran."}, {"key": "D", "text": "E-learning tentang sejarah perusahaan."}]'::jsonb,'A','Untuk melatih keterampilan interpersonal seperti komunikasi, metode yang melibatkan praktik aktif jauh lebih efektif daripada metode pasif. Role-playing memungkinkan peserta untuk mempraktikkan cara menangani situasi sulit (seperti pelanggan yang marah) dalam lingkungan yang aman dan mendapatkan umpan balik langsung.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam sebuah rapat tim proyek PLN, mayoritas anggota setuju pada sebuah ide yang kurang realistis hanya karena tidak ingin menentang pendapat manajer proyek yang karismatik. Fenomena ini disebut...','[{"key": "A", "text": "Social Loafing"}, {"key": "B", "text": "Polarisasi Kelompok"}, {"key": "C", "text": "Groupthink"}, {"key": "D", "text": "Konflik Interpersonal"}]'::jsonb,'A','Groupthink adalah fenomena psikologis di mana keinginan kelompok untuk mencapai konsensus mengalahkan keinginan untuk mengevaluasi alternatif secara realistis. Anggota kelompok cenderung menekan perbedaan pendapat demi menjaga keharmonisan, yang sering kali mengarah pada pengambilan keputusan yang buruk.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Konflik antara divisi transmisi dan distribusi PLN mengenai jadwal pemeliharaan jaringan dapat menjadi konflik yang fungsional jika...','[{"key": "A", "text": "Konflik tersebut menyebabkan permusuhan pribadi."}, {"key": "B", "text": "Mendorong diskusi yang menghasilkan solusi penjadwalan yang lebih efisien."}, {"key": "C", "text": "Salah satu pihak mengalah demi menghindari perdebatan."}, {"key": "D", "text": "Masalah tersebut diabaikan dan tidak pernah dibahas."}]'::jsonb,'A','Tidak semua konflik itu buruk. Konflik fungsional (atau konstruktif) berfokus pada tugas dan dapat merangsang debat, kreativitas, dan pertimbangan ide-ide baru, yang pada akhirnya mengarah pada solusi yang lebih baik. Ini berbeda dengan konflik disfungsional yang bersifat personal dan merusak hubungan kerja.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Cara paling efektif untuk seorang supervisor mengatasi konflik personal antara dua teknisi di dalam timnya adalah...','[{"key": "A", "text": "Membiarkan mereka menyelesaikan masalahnya sendiri."}, {"key": "B", "text": "Memindahkan salah satu teknisi ke tim lain tanpa diskusi."}, {"key": "C", "text": "Bertindak sebagai mediator untuk memfasilitasi komunikasi yang konstruktif."}, {"key": "D", "text": "Menjatuhkan sanksi kepada keduanya agar tidak mengulangi."}]'::jsonb,'A','Peran seorang pemimpin dalam menangani konflik interpersonal adalah sebagai fasilitator, bukan hakim. Tujuannya adalah membantu pihak yang berkonflik untuk saling mendengarkan, memahami perspektif masing-masing, dan menemukan solusi yang dapat diterima bersama, sehingga hubungan kerja dapat dipulihkan.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ketika PLN akan melakukan modernisasi sistem pencatatan meteran listrik, komunikasi yang efektif kepada tim lapangan sangat penting untuk...','[{"key": "A", "text": "Menunjukkan kekuasaan manajemen."}, {"key": "B", "text": "Mengurangi resistensi terhadap perubahan dan memastikan transisi berjalan lancar."}, {"key": "C", "text": "Membuat karyawan merasa takut dan patuh."}, {"key": "D", "text": "Memenuhi formalitas administrasi."}]'::jsonb,'A','Manusia secara alami cenderung menolak perubahan karena ketidakpastian. Komunikasi yang efektif menjelaskan alasan perubahan, manfaatnya, dan bagaimana dampaknya akan dikelola. Ini membantu mengurangi kecemasan, menjawab pertanyaan, dan membangun dukungan dari karyawan.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang teknisi senior melihat adanya prosedur keselamatan kerja yang kadang diabaikan oleh rekan-rekannya demi mempercepat pekerjaan. Keinginan teknisi tersebut untuk tetap mengikuti prosedur meskipun berbeda dari yang lain menunjukkan perlawanan terhadap...','[{"key": "A", "text": "Konformitas"}, {"key": "B", "text": "Otoritas"}, {"key": "C", "text": "Kohesi kelompok"}, {"key": "D", "text": "Norma kerja"}]'::jsonb,'A','Konformitas adalah tekanan sosial (nyata atau dibayangkan) untuk menyesuaikan perilaku agar sesuai dengan norma kelompok. Menolak konformitas demi menegakkan aturan atau prinsip yang benar (seperti keselamatan kerja) menunjukkan integritas dan kemandirian berpikir.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam proyek tim yang besar, beberapa anggota tim PLN mungkin akan mengurangi usaha personal mereka dan mengandalkan kerja keras anggota lain. Fenomena ini dikenal sebagai...','[{"key": "A", "text": "Sinergi tim"}, {"key": "B", "text": "Social loafing"}, {"key": "C", "text": "Kompetisi internal"}, {"key": "D", "text": "Efek fasilitasi sosial"}]'::jsonb,'A','Fenomena ini terjadi karena adanya difusi tanggung jawab; ketika bekerja dalam kelompok, individu mungkin merasa kontribusi pribadinya kurang terlihat atau kurang penting, sehingga mereka cenderung mengurangi usaha dibandingkan jika mereka bekerja sendirian.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Komunikasi interpersonal yang baik antar staf di unit pembangkitan sangat krusial karena...','[{"key": "A", "text": "Membuat suasana kerja menjadi lebih santai."}, {"key": "B", "text": "Kesalahan komunikasi dapat berakibat fatal pada operasional dan keselamatan."}, {"key": "C", "text": "Meningkatkan popularitas manajer unit."}, {"key": "D", "text": "Membantu memenangkan penghargaan perusahaan."}]'::jsonb,'A','Di lingkungan kerja teknis dan berisiko tinggi, seperti unit pembangkitan, kejelasan dan ketepatan komunikasi bukanlah sekadar "nice to have", melainkan sebuah keharusan. Instruksi yang salah dipahami atau informasi penting yang tidak tersampaikan dapat menyebabkan kerusakan peralatan, pemadaman, atau kecelakaan kerja.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang psikolog yang bekerja di departemen SDM PLN melakukan sesi konseling dengan seorang karyawan yang mengalami stres. Psikolog tersebut wajib menjaga kerahasiaan isi konseling, kecuali jika...','[{"key": "A", "text": "Atasan karyawan tersebut memintanya untuk tujuan penilaian kinerja."}, {"key": "B", "text": "Ada indikasi kuat karyawan tersebut akan membahayakan diri sendiri atau orang lain."}, {"key": "C", "text": "Rekan kerja karyawan tersebut penasaran dengan masalahnya."}, {"key": "D", "text": "Pihak manajemen ingin tahu masalah pribadi karyawannya."}]'::jsonb,'A','Kerahasiaan adalah pilar utama dalam etika konseling. Namun, prinsip ini memiliki batasan absolut ketika ada ancaman nyata terhadap kehidupan. Dalam situasi seperti itu, kewajiban etis psikolog beralih dari menjaga kerahasiaan menjadi melindungi keselamatan (duty to protect).','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kode Etik HIMPSI (Himpunan Psikologi Indonesia) relevan bagi praktisi SDM di PLN, terutama dalam hal...','[{"key": "A", "text": "Penggunaan alat tes psikologi secara bertanggung jawab."}, {"key": "B", "text": "Penetapan target Key Performance Indicator (KPI)."}, {"key": "C", "text": "Perancangan struktur gaji dan tunjangan."}, {"key": "D", "text": "Pemilihan seragam kerja perusahaan."}]'::jsonb,'A','Kode Etik HIMPSI secara spesifik mengatur penggunaan instrumen psikologi, termasuk siapa yang berhak menggunakannya, bagaimana menjaga keamanannya, dan bagaimana menginterpretasikan hasilnya secara etis. Hal ini untuk memastikan tes digunakan secara profesional dan tidak merugikan individu yang di tes.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu nilai utama dalam core values BUMN, yaitu AKHLAK, yang paling berkaitan erat dengan prinsip tidak membeda-bedakan kandidat berdasarkan SARA dalam proses rekrutmen adalah...','[{"key": "A", "text": "Amanah"}, {"key": "B", "text": "Kompeten"}, {"key": "C", "text": "Harmonis"}, {"key": "D", "text": "Loyal"}]'::jsonb,'A','Nilai AKHLAK "Harmonis" secara eksplisit mencakup sikap saling peduli dan menghargai perbedaan. Menerapkan nilai ini dalam rekrutmen berarti menciptakan lingkungan seleksi yang inklusif dan adil, di mana setiap kandidat dinilai berdasarkan kompetensinya, bukan latar belakang SARA-nya.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika seorang staf rekrutmen PLN menyadari bahwa salah satu kandidat adalah kerabatnya, tindakan yang paling etis untuk dilakukan adalah...','[{"key": "A", "text": "Meloloskan kerabatnya untuk membantunya."}, {"key": "B", "text": "Mengabaikan fakta tersebut dan melanjutkan proses seperti biasa."}, {"key": "C", "text": "Mengungkapkan adanya potensi konflik kepentingan kepada atasan atau panitia seleksi."}, {"key": "D", "text": "Memberikan soal tes yang lebih sulit kepada kerabatnya agar terlihat adil."}]'::jsonb,'A','Tindakan yang paling etis dan profesional adalah transparansi. Dengan memberitahukan adanya hubungan personal, staf tersebut melindungi integritas proses seleksi dan memungkinkan perusahaan untuk mengambil langkah mitigasi, seperti menugaskan penilai lain untuk kandidat tersebut.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pelanggaran etika profesi dalam proses asesmen SDM di PLN, seperti membocorkan soal psikotes kepada kandidat tertentu, akan merusak...','[{"key": "A", "text": "Citra perusahaan di mata investor."}, {"key": "B", "text": "Integritas dan objektivitas dari proses seleksi."}, {"key": "C", "text": "Anggaran tahunan departemen SDM."}, {"key": "D", "text": "Hubungan industrial dengan serikat pekerja."}]'::jsonb,'A','Pelanggaran etika seperti ini secara langsung merusak tujuan utama dari proses asesmen, yaitu untuk mengidentifikasi kandidat terbaik secara adil. Jika prosesnya tidak dapat dipercaya, maka hasilnya pun tidak valid, dan perusahaan berisiko merekrut orang yang tidak kompeten.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang operator di control room Pembangkit Listrik Tenaga Uap (PLTU) harus memantau banyak layar monitor secara bersamaan. Kemampuannya untuk fokus pada sinyal alarm yang paling kritis di antara banyak informasi lainnya adalah contoh dari...','[{"key": "A", "text": "Persepsi"}, {"key": "B", "text": "Memori jangka pendek"}, {"key": "C", "text": "Atensi selektif"}, {"key": "D", "text": "Sensasi"}]'::jsonb,'A','Atensi selektif adalah kemampuan kognitif untuk memproses informasi yang relevan sambil mengabaikan distraksi atau informasi lain yang tidak relevan. Ini adalah keterampilan krusial bagi operator yang bekerja di lingkungan yang kaya akan stimulus.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut teori atribusi, jika seorang manajer secara konsisten menyalahkan faktor eksternal (misalnya, cuaca buruk, peralatan tua) setiap kali timnya gagal mencapai target, ia menunjukkan...','[{"key": "A", "text": "Bias atribusi fundamental"}, {"key": "B", "text": "Bias self-serving"}, {"key": "C", "text": "Locus of control eksternal"}, {"key": "D", "text": "Locus of control internal"}]'::jsonb,'A','Locus of control mengacu pada sejauh mana individu percaya bahwa mereka dapat mengendalikan peristiwa yang memengaruhi mereka. Seseorang dengan locus of control eksternal cenderung percaya bahwa nasib, keberuntungan, atau kekuatan luar yang menentukan hasil, sehingga mereka menyalahkan faktor eksternal atas kegagalan.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang karyawan baru di PLN merasa cemas saat pertama kali presentasi di depan manajer senior. Jantungnya berdebar kencang, dan kemudian ia menyimpulkan bahwa ia merasa takut. Penjelasan ini paling sesuai dengan teori emosi...','[{"key": "A", "text": "Cannon-Bard"}, {"key": "B", "text": "James-Lange"}, {"key": "C", "text": "Schachter-Singer (Dua Faktor)"}, {"key": "D", "text": "Teori Kognitif Apraisal"}]'::jsonb,'A','Teori ini menyatakan bahwa emosi adalah hasil dari interpretasi kita terhadap respons fisiologis tubuh. Urutannya adalah: stimulus (presentasi) -> respons fisiologis (jantung berdebar) -> interpretasi respons sebagai emosi (rasa takut).','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam model kepribadian "The Big Five", seorang insinyur di divisi riset dan pengembangan PLN yang sangat imajinatif, penuh ide baru, dan suka mencoba metode-metode non-konvensional kemungkinan besar memiliki skor tinggi pada dimensi...','[{"key": "A", "text": "Conscientiousness"}, {"key": "B", "text": "Extraversion"}, {"key": "C", "text": "Agreeableness"}, {"key": "D", "text": "Openness to Experience"}]'::jsonb,'A','Dimensi ini mencakup ciri-ciri seperti imajinasi, keingintahuan intelektual, keterbukaan terhadap ide-ide baru, dan preferensi pada variasi. Ini sangat cocok untuk peran yang membutuhkan kreativitas dan inovasi seperti di R&D.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pegawai senior PLN yang aktif membimbing juniornya, berbagi pengetahuan, dan berkontribusi pada regenerasi perusahaan, menurut teori perkembangan psikososial Erikson, berada dalam tahap...','[{"key": "A", "text": "Intimacy vs. Isolation"}, {"key": "B", "text": "Identity vs. Role Confusion"}, {"key": "C", "text": "Generativity vs. Stagnation"}, {"key": "D", "text": "Ego Integrity vs. Despair"}]'::jsonb,'A','Tahap ini terjadi pada usia dewasa pertengahan, di mana fokus utamanya adalah berkontribusi pada masyarakat dan generasi berikutnya (generativitas), misalnya melalui bimbingan, pengasuhan, atau pekerjaan yang bermakna. Kegagalan dalam tahap ini menyebabkan perasaan stagnan.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ketika melakukan investigasi penyebab gangguan listrik, seorang investigator yang hanya mencari bukti yang mendukung hipotesis awalnya dan mengabaikan bukti yang bertentangan, menunjukkan adanya...','[{"key": "A", "text": "Bias konfirmasi (confirmation bias)"}, {"key": "B", "text": "Efek halo"}, {"key": "C", "text": "Hindsight bias"}, {"key": "D", "text": "Anchoring bias"}]'::jsonb,'A','Ini adalah kecenderungan kognitif untuk mencari, menafsirkan, dan mengingat informasi dengan cara yang mengonfirmasi keyakinan atau hipotesis yang sudah ada sebelumnya. Ini adalah penghalang besar untuk pemecahan masalah yang objektif.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses mental yang memungkinkan seorang teknisi untuk mengingat urutan langkah-langkah kompleks dalam memperbaiki sebuah mesin bahkan setelah lama tidak melakukannya disebut...','[{"key": "A", "text": "Memori sensorik"}, {"key": "B", "text": "Memori episodik"}, {"key": "C", "text": "Memori semantik"}, {"key": "D", "text": "Memori prosedural"}]'::jsonb,'A','Ini adalah jenis memori jangka panjang yang bertanggung jawab untuk mengetahui bagaimana melakukan sesuatu, juga dikenal sebagai memori motorik. Memori ini menyimpan prosedur atau langkah-langkah melakukan suatu tindakan, seperti mengendarai sepeda atau memperbaiki mesin.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut Teori ERG Alderfer, seorang karyawan yang merasa frustrasi karena kebutuhan pertumbuhannya (Growth) terhambat (misalnya, tidak ada promosi) mungkin akan lebih fokus untuk memenuhi kebutuhan keterkaitan (Relatedness) dengan mempererat hubungan dengan rekan kerja. Fenomena ini disebut...','[{"key": "A", "text": "Satisfaction-progression"}, {"key": "B", "text": "Frustration-regression"}, {"key": "C", "text": "Existence needs"}, {"key": "D", "text": "Relatedness needs"}]'::jsonb,'A','Prinsip ini adalah bagian unik dari teori ERG yang menyatakan bahwa jika kebutuhan tingkat yang lebih tinggi (misalnya, Growth) terhalang, individu akan kembali (regresi) untuk lebih memuaskan kebutuhan tingkat yang lebih rendah (misalnya, Relatedness) yang lebih mudah dicapai.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang calon teknisi PLN sangat yakin bahwa jika ia berusaha keras (Upaya), ia pasti akan lulus tes keterampilan teknis (Kinerja), dan kelulusan ini akan memberinya pekerjaan yang ia inginkan (Hasil). Keyakinan ini merupakan inti dari Teori...','[{"key": "A", "text": "Penetapan Tujuan (Locke)"}, {"key": "B", "text": "Harapan (Vroom)"}, {"key": "C", "text": "Keadilan (Adams)"}, {"key": "D", "text": "Penguatan (Skinner)"}]'::jsonb,'A','Teori Harapan Vroom menyatakan bahwa motivasi adalah hasil dari tiga faktor: Harapan (keyakinan bahwa upaya akan menghasilkan kinerja), Instrumentality (keyakinan bahwa kinerja akan menghasilkan hasil/imbalan), dan Valensi (nilai dari hasil/imbalan tersebut bagi individu).','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kelelahan emosional, depersonalisasi (sikap sinis terhadap pekerjaan), dan penurunan pencapaian pribadi adalah tiga komponen utama dari...','[{"key": "A", "text": "Stres kerja akut"}, {"key": "B", "text": "Burnout (Keletihan kerja)"}, {"key": "C", "text": "Ketidakpuasan kerja"}, {"key": "D", "text": "Konflik peran"}]'::jsonb,'A','Burnout adalah sindrom psikologis sebagai respons terhadap stres kerja kronis yang tidak terkelola dengan baik. Tiga dimensi utamanya adalah kelelahan yang mendalam, perasaan sinis atau menjaga jarak dari pekerjaan, dan rasa inefisiensi atau penurunan prestasi kerja.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah tim proyek di PLN yang baru dibentuk sedang mengalami banyak perdebatan dan konflik internal mengenai peran, tanggung jawab, dan cara kerja terbaik. Menurut model Tuckman, tim ini berada dalam tahap...','[{"key": "A", "text": "Forming (Pembentukan)"}, {"key": "B", "text": "Storming (Badai)"}, {"key": "C", "text": "Norming (Penormalan)"}, {"key": "D", "text": "Performing (Pelaksanaan)"}]'::jsonb,'A','Tahap storming ditandai oleh konflik dan persaingan antar anggota tim saat mereka mulai menyuarakan pendapat dan ide-ide mereka yang berbeda. Ini adalah tahap yang normal dan perlu sebelum tim dapat beralih ke tahap norming di mana aturan dan peran mulai disepakati.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang kepala teknisi yang sangat dihormati karena keahlian teknisnya yang mendalam dan pengalamannya yang luas, memiliki jenis kekuasaan...','[{"key": "A", "text": "Legitimate Power (Kekuasaan Sah)"}, {"key": "B", "text": "Reward Power (Kekuasaan Imbalan)"}, {"key": "C", "text": "Expert Power (Kekuasaan Ahli)"}, {"key": "D", "text": "Coercive Power (Kekuasaan Paksaan)"}]'::jsonb,'A','Kekuasaan ini berasal dari pengetahuan, keterampilan, atau keahlian khusus yang dimiliki seseorang. Orang lain patuh atau mengikuti arahan karena mereka percaya pada keahlian dan penilaian orang tersebut, bukan karena posisi formalnya.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perilaku sukarela seorang karyawan yang melampaui deskripsi pekerjaannya, seperti membantu rekan kerja yang kesulitan tanpa diminta, disebut...','[{"key": "A", "text": "Kinerja dalam peran (In-role performance)"}, {"key": "B", "text": "Organizational Citizenship Behavior (OCB)"}, {"key": "C", "text": "Keterlibatan Karyawan"}, {"key": "D", "text": "Komitmen Organisasi"}]'::jsonb,'A','OCB adalah perilaku diskresioner individu yang tidak secara langsung atau eksplisit diakui oleh sistem imbalan formal, dan yang secara agregat mendorong fungsi organisasi yang efektif. Sederhananya, ini adalah perilaku "warga perusahaan yang baik".','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN menerapkan sistem kerja sif bagi operator gardu induk untuk memastikan operasional 24 jam. Salah satu tantangan psikologis utama yang dihadapi pekerja sif adalah...','[{"key": "A", "text": "Kurangnya kesempatan promosi"}, {"key": "B", "text": "Gangguan pada ritme sirkadian (jam biologis tubuh)"}, {"key": "C", "text": "Gaji yang lebih rendah dari pekerja non-sif"}, {"key": "D", "text": "Terlalu banyak waktu luang"}]'::jsonb,'A','Bekerja di luar jam normal (terutama sif malam) dapat mengganggu jam internal tubuh yang mengatur siklus tidur-bangun, suhu tubuh, dan pelepasan hormon. Gangguan ini dapat menyebabkan masalah tidur, kelelahan, dan masalah kesehatan jangka panjang.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kesepakatan tidak tertulis yang berisi ekspektasi timbal balik antara karyawan dan perusahaan (misalnya, karyawan berharap pengembangan karir, perusahaan berharap loyalitas) disebut...','[{"key": "A", "text": "Kontrak kerja"}, {"key": "B", "text": "Perjanjian kerja bersama"}, {"key": "C", "text": "Kontrak psikologis"}, {"key": "D", "text": "Deskripsi jabatan"}]'::jsonb,'A','Ini adalah seperangkat keyakinan dan ekspektasi yang tidak tertulis tentang apa yang akan diberikan dan diterima oleh karyawan dan perusahaan dalam hubungan kerja mereka. Pelanggaran kontrak ini, meskipun tidak tertulis, dapat menyebabkan penurunan kepercayaan dan kepuasan kerja.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah kuesioner meminta karyawan PLN untuk menilai program pelatihan baru dengan menempatkan tanda pada sebuah garis antara dua kata sifat berlawanan (misal: Membosankan --- Menarik). Jenis skala ini adalah...','[{"key": "A", "text": "Skala Likert"}, {"key": "B", "text": "Skala Guttman"}, {"key": "C", "text": "Skala Diferensial Semantik"}, {"key": "D", "text": "Skala Thurstone"}]'::jsonb,'A','Skala ini mengukur makna konotatif dari sebuah konsep dengan meminta responden untuk menilainya pada serangkaian skala bipolar (dua kutub kata sifat yang berlawanan).','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tim SDM PLN ingin memastikan bahwa tes kepemimpinan yang mereka gunakan benar-benar mengukur konstruk psikologis ''potensi kepemimpinan'' dan bukan hal lain. Upaya untuk membuktikan hal ini berkaitan dengan...','[{"key": "A", "text": "Validitas isi"}, {"key": "B", "text": "Validitas kriteria"}, {"key": "C", "text": "Validitas konstruk"}, {"key": "D", "text": "Reliabilitas"}]'::jsonb,'A','Validitas konstruk adalah jenis validitas yang paling fundamental dan menyeluruh. Ini mengacu pada sejauh mana sebuah tes secara akurat mengukur teori atau sifat psikologis (konstruk) yang menjadi tujuannya.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah tes baru untuk mengukur keterampilan pemecahan masalah teknisi PLN diberikan bersamaan dengan tes lain yang sudah terbukti valid. Jika skor dari kedua tes tersebut berkorelasi tinggi, maka tes baru tersebut memiliki...','[{"key": "A", "text": "Validitas prediktif"}, {"key": "B", "text": "Validitas konkuren (concurrent validity)"}, {"key": "C", "text": "Validitas muka (face validity)"}, {"key": "D", "text": "Reliabilitas belah dua"}]'::jsonb,'A','Ini adalah salah satu jenis validitas berbasis kriteria di mana hasil dari alat ukur baru dibandingkan dengan hasil dari kriteria atau alat ukur lain yang sudah mapan yang diukur pada waktu yang bersamaan (konkuren). Korelasi yang tinggi menunjukkan validitas yang baik.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pada saat seleksi, seorang kandidat berusaha menampilkan citra diri yang sangat ideal pada tes kepribadian, misalnya menjawab semua pertanyaan agar terlihat sangat stabil secara emosional dan sangat ramah. Perilaku ini disebut...','[{"key": "A", "text": "Social desirability bias atau faking good"}, {"key": "B", "text": "Bias respon sentral"}, {"key": "C", "text": "Bias akuiesens (cenderung setuju)"}, {"key": "D", "text": "Kesalahan pengukuran acak"}]'::jsonb,'A','Ini adalah kecenderungan responden tes untuk menjawab pertanyaan dengan cara yang akan dipandang baik oleh orang lain. Ini merupakan masalah umum dalam seleksi kerja, di mana kandidat termotivasi untuk menampilkan diri mereka dalam cahaya yang paling positif.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk mengetahui apakah skor seorang kandidat PLN dalam tes kemampuan numerik termasuk "di atas rata-rata", "rata-rata", atau "di bawah rata-rata", skor mentahnya harus dibandingkan dengan...','[{"key": "A", "text": "Skor kandidat lain pada hari yang sama"}, {"key": "B", "text": "Skor minimal kelulusan yang ditetapkan perusahaan"}, {"key": "C", "text": "Norma kelompok (distribusi skor dari kelompok referensi)"}, {"key": "D", "text": "Skor kandidat tersebut pada tes verbal"}]'::jsonb,'A','Skor mentah dari sebuah tes psikometri (misalnya, 30 dari 50) tidak memiliki arti tanpa konteks. Dengan membandingkannya dengan norma (misalnya, distribusi skor dari semua calon teknisi sebelumnya), kita dapat menentukan posisi relatif individu tersebut (misalnya, di persentil ke-80).','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika sebuah tes kepribadian memiliki pertanyaan yang ambigu dan dapat ditafsirkan berbeda oleh setiap orang, hal ini akan paling mengancam...','[{"key": "A", "text": "Reliabilitas tes"}, {"key": "B", "text": "Validitas muka"}, {"key": "C", "text": "Objektivitas skoring"}, {"key": "D", "text": "Norma tes"}]'::jsonb,'A','Reliabilitas adalah tentang konsistensi. Jika pertanyaan ambigu, maka peserta yang sama dapat menginterpretasikannya secara berbeda pada waktu yang berbeda, atau peserta yang berbeda dapat menginterpretasikannya secara berbeda. Ambiguitas ini menciptakan inkonsistensi atau "noise" dalam pengukuran, sehingga menurunkan reliabilitas.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam dokumen analisis jabatan, bagian yang merinci kualifikasi minimum yang harus dimiliki seseorang untuk dapat melakukan pekerjaan (misalnya, pendidikan S1 Teknik Elektro, sertifikasi K3 Listrik) disebut...','[{"key": "A", "text": "Deskripsi jabatan (job description)"}, {"key": "B", "text": "Spesifikasi jabatan (job specification)"}, {"key": "C", "text": "Evaluasi jabatan"}, {"key": "D", "text": "Desain jabatan"}]'::jsonb,'A','Analisis jabatan menghasilkan dua dokumen utama: deskripsi jabatan (tentang pekerjaan; tugas & tanggung jawab) dan spesifikasi jabatan (tentang orang; KSAO - Knowledge, Skills, Abilities, and Other characteristics).','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam wawancara, seorang rekruter PLN bertanya, "Bayangkan Anda adalah kepala regu pemeliharaan dan dua anggota tim Anda berselisih paham hingga tidak mau bekerja sama. Apa yang akan Anda lakukan?" Ini adalah contoh pertanyaan dari...','[{"key": "A", "text": "Wawancara behavioral"}, {"key": "B", "text": "Wawancara situasional"}, {"key": "C", "text": "Wawancara stres"}, {"key": "D", "text": "Wawancara panel"}]'::jsonb,'A','Wawancara situasional menyajikan kepada kandidat sebuah skenario hipotetis terkait pekerjaan ("Bayangkan jika...") dan menanyakan bagaimana mereka akan merespons. Ini bertujuan untuk mengukur niat perilaku dan kemampuan pemecahan masalah kandidat.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebelum menerima calon teknisi lapangan, tim rekrutmen PLN memberikan video yang menunjukkan suka dan duka pekerjaan tersebut secara realistis, termasuk bekerja di bawah terik matahari dan hujan. Praktik ini disebut...','[{"key": "A", "text": "Employer branding"}, {"key": "B", "text": "Wawancara realistis"}, {"key": "C", "text": "Realistic Job Preview (RJP)"}, {"key": "D", "text": "Orientasi kerja"}]'::jsonb,'A','RJP adalah alat rekrutmen yang memberikan informasi yang seimbang (positif dan negatif) tentang pekerjaan dan perusahaan. Tujuannya adalah untuk mengelola ekspektasi kandidat, yang dapat mengurangi turnover karyawan baru.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk mempersiapkan calon pilot helikopter inspeksi jaringan, PLN menggunakan simulator penerbangan yang sangat canggih dan mirip dengan kondisi nyata. Metode pelatihan ini disebut...','[{"key": "A", "text": "On-the-job training"}, {"key": "B", "text": "Vestibule training"}, {"key": "C", "text": "Apprenticeship (Magang)"}, {"key": "D", "text": "Studi kasus"}]'::jsonb,'A','Ini adalah bentuk pelatihan off-the-job yang menggunakan peralatan simulasi dalam lingkungan yang terpisah dari lokasi kerja sebenarnya. Ini sangat berguna untuk pekerjaan yang kompleks atau berisiko tinggi, di mana kesalahan dalam pelatihan di tempat kerja bisa berbahaya atau mahal.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Setelah mengadakan pelatihan K3, manajer SDM PLN mengukur apakah ada penurunan angka kecelakaan kerja di unit tersebut beberapa bulan kemudian. Menurut model evaluasi Kirkpatrick, ini adalah pengukuran pada level...','[{"key": "A", "text": "Reaksi (Reaction)"}, {"key": "B", "text": "Pembelajaran (Learning)"}, {"key": "C", "text": "Perilaku (Behavior)"}, {"key": "D", "text": "Hasil (Results)"}]'::jsonb,'A','Model Kirkpatrick memiliki 4 level: 1. Reaksi (apakah peserta menyukainya?), 2. Pembelajaran (apakah mereka belajar sesuatu?), 3. Perilaku (apakah mereka menerapkan apa yang dipelajari di pekerjaan?), dan 4. Hasil (apakah penerapan itu berdampak pada hasil bisnis seperti keselamatan, produktivitas, atau keuntungan?).','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah metode seleksi di mana sekelompok kandidat dikumpulkan dan dievaluasi melalui berbagai simulasi seperti diskusi kelompok tanpa pemimpin, studi kasus, dan presentasi disebut...','[{"key": "A", "text": "Tes psikometri massal"}, {"key": "B", "text": "Wawancara panel"}, {"key": "C", "text": "Pusat asesmen (Assessment Center)"}, {"key": "D", "text": "Tes pengetahuan umum"}]'::jsonb,'A','Assessment Center bukanlah sebuah tempat, melainkan sebuah metode yang menggunakan berbagai teknik evaluasi dan beberapa asesor terlatih untuk menilai kompetensi manajerial atau kepemimpinan kandidat.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses sistematis untuk mengidentifikasi dan mengembangkan karyawan internal dengan potensi untuk mengisi posisi kepemimpinan kunci di masa depan di PLN disebut...','[{"key": "A", "text": "Rotasi jabatan"}, {"key": "B", "text": "Perencanaan suksesi (succession planning)"}, {"key": "C", "text": "Program pensiun"}, {"key": "D", "text": "Penilaian kinerja"}]'::jsonb,'A','Ini adalah proses proaktif untuk memastikan kelangsungan kepemimpinan dalam posisi-posisi kritis dengan mempersiapkan talenta internal untuk mengambil alih peran tersebut ketika terjadi kekosongan.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang teknisi yang biasanya bekerja dengan sangat teliti, ternyata bekerja lebih cepat dan sedikit lebih ceroboh saat ada supervisor yang mengawasinya. Peningkatan kecepatan pada tugas yang dikuasai dengan baik karena kehadiran orang lain ini disebut...','[{"key": "A", "text": "Social loafing"}, {"key": "B", "text": "Fasilitasi sosial"}, {"key": "C", "text": "Groupthink"}, {"key": "D", "text": "Deindividuasi"}]'::jsonb,'A','Ini adalah kecenderungan orang untuk berkinerja lebih baik pada tugas-tugas sederhana atau yang telah dipelajari dengan baik ketika mereka berada di hadapan orang lain. Namun, untuk tugas yang sulit atau baru, kehadiran orang lain justru dapat mengganggu kinerja.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam negosiasi antara serikat pekerja dan manajemen PLN, kedua belah pihak setuju untuk mencari solusi yang dapat memuaskan kepentingan keduanya secara maksimal, meskipun membutuhkan waktu dan usaha lebih. Gaya resolusi konflik ini adalah...','[{"key": "A", "text": "Competing (Bersaing)"}, {"key": "B", "text": "Accommodating (Mengakomodasi)"}, {"key": "C", "text": "Avoiding (Menghindar)"}, {"key": "D", "text": "Collaborating (Berkolaborasi)"}]'::jsonb,'A','Gaya ini memiliki tingkat ketegasan (assertiveness) dan kerja sama (cooperativeness) yang tinggi. Pihak-pihak yang berkonflik berusaha untuk menemukan solusi "menang-menang" (win-win) yang sepenuhnya memuaskan kepentingan semua pihak.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tim pemeliharaan gardu induk PLN sangat kompak, anggotanya saling menyukai, dan memiliki komitmen tinggi terhadap tujuan tim. Karakteristik ini menunjukkan tim tersebut memiliki... yang tinggi.','[{"key": "A", "text": "Kohesivitas kelompok"}, {"key": "B", "text": "Polarisasi kelompok"}, {"key": "C", "text": "Ukuran kelompok"}, {"key": "D", "text": "Status kelompok"}]'::jsonb,'A','Kohesivitas adalah "lem" yang menyatukan kelompok, mencakup daya tarik interpersonal antar anggota dan komitmen mereka terhadap tugas kelompok. Kohesivitas yang tinggi sering kali berkorelasi dengan kinerja yang lebih baik.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pengumuman resmi mengenai perubahan kebijakan K3 di PLN yang disebarkan melalui email dari direksi adalah contoh dari...','[{"key": "A", "text": "Komunikasi informal"}, {"key": "B", "text": "Komunikasi formal (ke bawah)"}, {"key": "C", "text": "Komunikasi horizontal"}, {"key": "D", "text": "Gosip (grapevine)"}]'::jsonb,'A','Komunikasi formal mengikuti struktur hierarki resmi organisasi. Komunikasi dari manajemen tingkat atas ke karyawan tingkat bawah (seperti pengumuman kebijakan) adalah contoh komunikasi ke bawah (downward communication).','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika seorang teknisi melihat adanya kondisi tidak aman di area kerja tetapi tidak melaporkannya karena berpikir "pasti sudah ada orang lain yang akan melaporkan," ia menunjukkan fenomena...','[{"key": "A", "text": "Konformitas"}, {"key": "B", "text": "Efek pengamat (bystander effect)"}, {"key": "C", "text": "Kepatuhan pada otoritas"}, {"key": "D", "text": "Polarisasi kelompok"}]'::jsonb,'A','Fenomena sosial-psikologis ini mengacu pada kasus di mana individu cenderung tidak menawarkan bantuan kepada korban ketika orang lain hadir. Adanya orang lain menciptakan difusi tanggung jawab.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer proyek PLN berhasil meyakinkan timnya untuk bekerja lembur di akhir pekan bukan karena jabatannya, tetapi karena tim tersebut sangat mengagumi dan menghormatinya sebagai pribadi. Kekuasaan yang dimiliki manajer ini adalah...','[{"key": "A", "text": "Expert Power"}, {"key": "B", "text": "Legitimate Power"}, {"key": "C", "text": "Referent Power"}, {"key": "D", "text": "Reward Power"}]'::jsonb,'A','Kekuasaan ini didasarkan pada karisma, identifikasi, dan kekaguman pengikut terhadap pemimpin. Orang mengikuti karena mereka ingin menjadi seperti pemimpin tersebut atau karena mereka merasa memiliki hubungan pribadi yang kuat dengannya.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk meyakinkan departemen lain agar mengadopsi sistem IT baru, seorang manajer menampilkan data dan testimoni dari para ahli untuk menunjukkan keunggulan sistem tersebut. Rute persuasi yang ia gunakan adalah...','[{"key": "A", "text": "Rute sentral (central route)"}, {"key": "B", "text": "Rute periferal (peripheral route)"}, {"key": "C", "text": "Rute emosional"}, {"key": "D", "text": "Rute heuristik"}]'::jsonb,'A','Menurut Elaboration Likelihood Model, persuasi rute sentral terjadi ketika seseorang diyakinkan oleh isi dan kekuatan argumen itu sendiri (data, fakta, logika). Ini memerlukan pemikiran yang cermat dan biasanya menghasilkan perubahan sikap yang lebih tahan lama.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebelum memulai proses asesmen untuk pengembangan karir, seorang psikolog di PLN menjelaskan tujuan, proses, dan bagaimana hasil asesmen akan digunakan, lalu meminta persetujuan dari karyawan yang bersangkutan. Prinsip etika yang diterapkan adalah...','[{"key": "A", "text": "Kerahasiaan"}, {"key": "B", "text": "Persetujuan setelah penjelasan (informed consent)"}, {"key": "C", "text": "Kompetensi"}, {"key": "D", "text": "Objektivitas"}]'::jsonb,'A','Ini adalah prinsip etis yang mengharuskan profesional untuk memberikan informasi yang cukup kepada klien/peserta tentang prosedur yang akan dilakukan, termasuk risiko dan manfaatnya, sehingga mereka dapat membuat keputusan yang terinformasi untuk berpartisipasi atau tidak.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang praktisi SDM di PLN yang juga membuka praktik konseling pribadi di luar jam kerja diminta untuk menangani kasus seleksi di mana salah satu kandidat adalah klien konselingnya. Situasi ini menciptakan potensi masalah etika yang disebut...','[{"key": "A", "text": "Konflik kepentingan"}, {"key": "B", "text": "Hubungan ganda (dual relationship)"}, {"key": "C", "text": "Pelanggaran kerahasiaan"}, {"key": "D", "text": "Diskriminasi"}]'::jsonb,'A','Hubungan ganda terjadi ketika seorang profesional memiliki dua atau lebih jenis hubungan yang berbeda dengan orang yang sama (misalnya, terapis dan penyeleksi, atasan dan teman dekat). Hubungan ini harus dihindari karena berpotensi merusak objektivitas dan mengeksploitasi klien/karyawan.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Nilai AKHLAK "Kompeten" bagi seorang profesional SDM di PLN berarti memiliki kewajiban etis untuk...','[{"key": "A", "text": "Menjaga nama baik sesama rekan BUMN."}, {"key": "B", "text": "Terus belajar dan meningkatkan keahlian sesuai perkembangan ilmu psikologi dan praktik SDM."}, {"key": "C", "text": "Selalu patuh pada perintah atasan tanpa kecuali."}, {"key": "D", "text": "Mendedikasikan seluruh waktu untuk kepentingan bangsa dan negara."}]'::jsonb,'A','Kompetensi dalam konteks profesional bukanlah kondisi statis. Ini adalah kewajiban etis untuk terus mengembangkan diri, mengikuti riset terbaru, dan memastikan bahwa praktik yang dilakukan didasarkan pada pengetahuan yang mutakhir dan efektif.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Departemen SDM PLN menyimpan data hasil psikotes seluruh karyawan dalam server yang terenkripsi dan aksesnya sangat terbatas. Tindakan ini merupakan penerapan prinsip etika dalam hal...','[{"key": "A", "text": "Keamanan data dan kerahasiaan"}, {"key": "B", "text": "Persetujuan tindakan"}, {"key": "C", "text": "Integritas asesmen"}, {"key": "D", "text": "Hubungan profesional"}]'::jsonb,'A','Profesional SDM dan psikolog memiliki kewajiban etis untuk melindungi informasi pribadi dan sensitif klien atau karyawan. Ini termasuk mengambil langkah-langkah teknis (seperti enkripsi) dan prosedural (pembatasan akses) untuk mencegah akses yang tidak sah.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penggunaan sistem rekrutmen berbasis AI di PLN memiliki risiko etis jika algoritma yang digunakan ternyata secara tidak sengaja lebih menyukai kandidat dari latar belakang tertentu, sehingga menyebabkan bias sistemik. Masalah ini berkaitan dengan...','[{"key": "A", "text": "Keamanan data"}, {"key": "B", "text": "Kerahasiaan"}, {"key": "C", "text": "Keadilan (fairness) dan diskriminasi"}, {"key": "D", "text": "Hak cipta algoritma"}]'::jsonb,'A','Salah satu tantangan etis terbesar dari AI dalam SDM adalah potensi bias yang tersembunyi. Jika AI dilatih dengan data historis yang bias, ia dapat belajar dan melanggengkan pola diskriminatif tersebut, sehingga melanggar prinsip keadilan dan kesempatan yang sama bagi semua kandidat.','AKDING',40);
